import 'package:cephalopod/features/game/presentation/models/player_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'headline_ui.freezed.dart';

/// What the line above the board says: whose turn it is, or who won and by
/// how much. One case per message, so each maps to exactly one translation.
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
sealed class HeadlineUi with _$HeadlineUi {
  /// "Player 1 to move", between two people.
  const factory HeadlineUi.playerToMove(PlayerUi player) = PlayerToMoveHeadline;

  /// "Your turn", against the computer.
  const factory HeadlineUi.yourTurn() = YourTurnHeadline;

  /// "The computer is thinking…".
  const factory HeadlineUi.computerThinking() = ComputerThinkingHeadline;

  /// "Player 2 wins 13 to 12", between two people: the winner's dice first.
  const factory HeadlineUi.playerWon({
    required PlayerUi player,
    required int winnerDice,
    required int loserDice,
  }) = PlayerWonHeadline;

  /// "You win 13 to 12", against the computer.
  const factory HeadlineUi.youWon({
    required int winnerDice,
    required int loserDice,
  }) = YouWonHeadline;

  /// "The computer wins 13 to 12".
  const factory HeadlineUi.computerWon({
    required int winnerDice,
    required int loserDice,
  }) = ComputerWonHeadline;
}
